from analyze import main as analyze, MAXIMA

ROOT=Path(__file__).resolve().parent
OUT=ROOT.parent
analyze()
DATA=json.loads((ROOT/'scores.json').read_text())
BY_ID={t['id']:t for t in DATA}
CSS=(ROOT/'report.css').read_text()
# Embedded font data keeps direct file opening independent of font CORS policies.
CSS=re.sub(r'url\(fonts/([^)]*)\)',lambda m:'url(data:font/ttf;base64,'+base64.b64encode((ROOT/'fonts'/m[1]).read_bytes()).decode()+')',CSS)
