BOOK='https://refactoringui.com/'
E=html.escape

def web(slug,label):
    return f'<a href="https://practicaltypography.com/{slug}.html">{label}</a>'

def book(pages):
    return f'<span class="caption">Refactoring UI, pp. {pages} (page numbers match the supplied PDF).</span>'

def page(filename,title,kicker,lede,body,script=''):
    nav=''.join(f'<a href="{f}"'+(' aria-current="page"' if f==filename else '')+f'>{label}</a>' for f,label in NAV)
    result=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{E(title)} · Elegant</title><meta name="description" content="{E(lede)}"><style>{CSS}</style></head>
<body><a class="skip" href="#main">Skip to content</a><div class="topbar"><nav aria-label="The four reports"><a class="brand" href="index.html">Elegant / Field notes</a>{nav}</nav></div>
<main id="main"><header class="hero"><p class="eyebrow">{kicker} · 16 October 2026</p><h1>{title}</h1><p class="lede">{lede}</p></header>{body}
<footer><p>Prepared for the Elegant / SmallDocs theme collection. Scores and examples are this review’s interpretation, not endorsements or official grading systems from either author.</p><p>All four pages work from local files. Keep the adjacent <code>typography-audit</code> folder with them; it contains our screenshots, measurements, calculation source, and font licenses. The public site links the source books; no book PDF or extracts are distributed.</p><p><a href="typography-audit/scores.json">Scores</a> · <a href="typography-audit/measurements.json">Rendered measurements</a> · <a href="typography-audit/controls.json">Control measurements</a> · <a href="typography-audit/metadata.json">Snapshot and provenance</a></p></footer></main><script>{COMMON_JS}\n{script}</script></body></html>'''
    (OUT/filename).write_text(result)

COMMON_JS='''
document.querySelectorAll('[data-filter-table]').forEach(container=>{
 const rows=[...container.querySelectorAll('tbody tr')],query=container.querySelector('input[type=search]'),group=container.querySelector('[data-group]'),order=container.querySelector('[data-order]'),status=container.querySelector('output');
 function update(){const q=query.value.toLowerCase();rows.forEach(r=>r.hidden=!(r.dataset.search.includes(q)&&(group.value==='all'||r.dataset.group===group.value)));const visible=rows.filter(r=>!r.hidden);const key=order.value;rows.sort((a,b)=>key==='name'?a.dataset.name.localeCompare(b.dataset.name):Number(b.dataset[key])-Number(a.dataset[key])||a.dataset.name.localeCompare(b.dataset.name)).forEach(r=>container.querySelector('tbody').append(r));status.textContent=visible.length+' of '+rows.length+' themes';}
 query.addEventListener('input',update);group.addEventListener('change',update);order.addEventListener('change',update);update();
});
document.querySelectorAll('[data-demo-mode]').forEach(s=>s.addEventListener('change',()=>{
 const palettes=JSON.parse(s.dataset.palettes);s.closest('.custom-proposal').querySelectorAll('.demo').forEach(d=>{Object.entries(palettes[s.value]).forEach(([k,v])=>d.style.setProperty('--d'+k,v));});
}));
'''

def toc(items):
    return '<nav class="toc" aria-label="On this page">'+''.join(f'<a href="#{id}">{text}</a>' for id,text in items)+'</nav>'

def metric_score(n):
    return f'<span class="score">{n}</span><span class="meter" aria-hidden="true"><i style="width:{n}%"></i></span>'

def flags(t,include_controls=False):
    found=[]
    for m in t['modes']:
        mm=m['metrics']
        for key,label in [('bodyContrast','Body'),('linkContrast','Link'),('inlineContrast','Inline code')]:
            if mm[key][0]<4.5:found.append(f'{label} {mm[key][0]:.2f}:1 ({m["mode"]})')
        if mm['syntaxContrast']<4.5:found.append(f'Syntax {mm["syntaxContrast"]:.2f}:1 ({m["mode"]})')
        if mm['overflow']:found.append('Page overflow')
    if include_controls:
        for c in t['design']['contexts']:
            for v in c['failures']:found.append(f'{v["label"][:38]} {v["ratio"]:.2f}:1 ({c["mode"]})')
    return found

def table(design=False):
    rows=[]
    for t in sorted(DATA,key=lambda t:(-t['design']['total'] if design else -t['typography'],t['name'])):
        m=t['modes'][0]['metrics'];warnings=flags(t,True)
        state='<span class="tag warn">Contrast repair</span>' if warnings else '<span class="tag">Sampled text clears</span>'
        notes=t['design']['note'] if design else t['note']
        rows.append(f'''<tr class="{'custom' if t['group']=='custom' else ''}" data-search="{E((t['name']+' '+t['recommendation']+' '+notes).lower())}" data-name="{t['name']}" data-group="{t['group']}" data-type="{t['typography']}" data-ui="{t['design']['total']}"><td class="theme"><a href="#theme-{t['id']}">{t['name']}</a><br><small class="muted">{t['group']}</small></td><td class="num">{metric_score(t['typography'])}</td><td class="num">{metric_score(t['design']['total'])}</td><td>{m['bodySize']:g}px<br><small>{m['leading']:.2f} leading</small></td><td class="num">{m['measure']:.1f}<br><small>{m['mobileMeasure']:.1f} mobile</small></td><td class="note">{state}<br><small>{E(notes)}</small></td></tr>''')
    return f'''<div data-filter-table><div class="filters"><label>Find a theme<input type="search" placeholder="Name or observation"></label><label>Collection<select aria-label="Collection" data-group><option value="all">All themes</option><option value="custom">Custom</option><option value="bootswatch">Bootswatch</option><option value="bootstrap">Bootstrap</option><option value="refined">Reading refinements</option></select></label><label>Order<select aria-label="Order" data-order><option value="{'ui' if design else 'type'}">{'Design' if design else 'Typography'} score</option><option value="{'type' if design else 'ui'}">{'Typography' if design else 'Design'} score</option><option value="name">Name</option></select></label><output aria-live="polite">38 themes</output></div><div class="table-wrap"><table class="ranking"><caption class="small" style="text-align:left;padding:12px">All scores out of 100. No combined grand total; a contrast flag still requires repair.</caption><thead><tr><th scope="col">Theme</th><th class="num" scope="col">Type /100</th><th class="num" scope="col">Design /100</th><th scope="col">Desktop body</th><th class="num" scope="col">Chars / line*</th><th scope="col">Decision / observation</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div><p class="caption">*Mean of complete rendered lines in two shared paragraphs, excluding each paragraph’s final line. Mobile is a 390px CSS viewport. See the method for sampling limits. Paired themes use the lower light/dark total. Flags include prose, code, and sampled desktop control text from both assessments. Equal scores are ties; differences of a few points are not decisive.</p></div>'''

def evidence(id,mode='original',kind='typography',caption='',mobile=False):
    suffix='mobile' if mobile else 'desktop'
    f=f'typography-audit/assets/{id}-{mode}-{suffix}-{kind}.jpg'
    if not (OUT/f).exists():
        return ''
    return f'<figure class="evidence {"mobile" if mobile else "tall"}"><a href="{f}" aria-label="Open full screenshot: {id}, {mode}, {kind}"><img src="{f}" alt="Captured {id} {mode} {kind} specimen" loading="lazy"></a><figcaption>{caption}<small>Actual browser capture. Select the image for its full saved view.</small></figcaption></figure>'

def score_details(design=False):
    blocks=[]
    for t in sorted(DATA,key=lambda t:t['name']):
        body=f'<p>{E(t["design"]["note"] if design else t["note"])}</p>'
        if design:
            maxs=dict(hierarchy=25,spacing=20,color=20,layout=15,surfaces=10,personality=10)
            notes={
                'hierarchy':'Editorial judgment: content priority, secondary emphasis, and clarity of the control hierarchy.',
                'spacing':'Editorial judgment: grouping, repeated rhythm, and breathing room in the shared specimens.',
                'color':'Measured foreground contrast plus editorial palette coherence, stable surfaces, and non-color cues. Mode breakdown below.',
                'layout':'Editorial judgment informed by measured prose width, alignment, and the narrow prose/code layout. Mobile controls were not audited.',
                'surfaces':'Editorial judgment: useful separation and restrained use of borders, shadows, and effects.',
                'personality':'Editorial judgment: coherence and fit to this project’s elegant documentation brief.'}
            body+=''.join(f'<div class="score-row"><b>{k.title()}</b><strong>{v}/{maxs[k]}</strong><span>{notes[k]}</span></div>' for k,v in t['design']['scores'].items())
            for context in t['design']['contexts']:
                fail=context['failures']
                rows=''.join(f'<tr><td>{E(c["label"])}</td><td>{c["ratio"]:.2f}:1</td><td>{"Below 4.5:1" if c["ratio"]<4.5 else "Clears sampled threshold"}</td></tr>' for c in context['controlContrast'])
                body+=f'<details class="mode-detail"><summary>{context["mode"].title()} · color {context["color"]}/20 · {len(fail)} control text flags</summary><p class="small">Color parts: body {context["colorParts"]["body"]}/4, controls {context["colorParts"]["controls"]}/4, links {context["colorParts"]["links"]}/2, palette {context["colorParts"]["palette"]}/5, non-color cues {context["colorParts"]["nonColorCues"]}/3, stable surface {context["colorParts"]["stableSurface"]}/2.</p><div class="table-wrap"><table class="rubric"><thead><tr><th>Sampled label</th><th>Contrast</th><th>Result</th></tr></thead><tbody>{rows}</tbody></table></div></details>'
        else:
            for m in t['modes']:
                body+=f'<details class="mode-detail"><summary>{m["mode"].title()} · {m["total"]}/100</summary>'
                body+=''.join(f'<div class="score-row"><b>{k.title()}</b><strong>{v}/{MAXIMA[k]}</strong><span>{E(m["reasons"][k])}</span></div>' for k,v in m['scores'].items())
                body+=f'<p class="caption">Including paragraph-ending short lines, the desktop mean is {m["metrics"]["allLineMean"]:.1f} characters. This is recorded but not used for the capacity score.</p></details>'
        mode='dark' if t['paired'] and design else 'light' if t['paired'] else 'original'
        f=f'typography-audit/assets/{t["id"]}-{mode}-desktop-{"components" if design else "typography"}.jpg'
        live=f'https://rahuldave.com/elegant-themes/previews/{t["id"]}/{"components" if design else "typography"}.html?mode={mode}'
        warnings=flags(t,True)
        if warnings:body+='<h4>Measured text-contrast flags</h4><ul class="small">'+''.join(f'<li>{E(w)}</li>' for w in warnings)+'</ul>'
        body+=f'<p class="small"><a href="{f}">Saved screenshot</a> · <a href="{live}">Live specimen</a> · <a href="{t["source"]}">Theme source</a></p>'
        blocks.append(f'<details class="theme-detail" id="theme-{t["id"]}"><summary>{t["name"]} <span class="tag neutral">Type {t["typography"]} · Design {t["design"]["total"]}</span></summary><div class="detail-body">{body}</div></details>')
    return ''.join(blocks)

def shortlist():
    return '''<div class="grid"><div class="card"><h3>General-use candidates</h3><p><strong>Zephyr</strong> is the first stock theme to try. <strong>Simplex</strong> is a quiet red-accent alternative; <strong>Pulse</strong> is a straightforward purple option.</p><p class="small">Their sampled body, link, code, and normal-state control text clears 4.5:1. This is not a full accessibility certification. All would benefit from a narrower prose width.</p></div><div class="card"><h3>Choose for their character, then repair</h3><p><strong>Litera</strong> is the best stock editorial direction, but links, messages, and some buttons need contrast repairs. <strong>Darkly</strong> is the preferred stock dark direction after fixing outline controls and colored messages.</p><p class="small">Flatly is a reserve sans option after a broader link/message contrast pass. Solar is a reserve dark option with little contrast headroom.</p></div></div>'''

METHOD="""<section id="method"><h2>What was evaluated</h2><p>The comparison contains 38 designs: three revised custom themes, their three preserved originals, Tufte, native Bootstrap, all 25 unchanged Bootswatches, and five independent Reading refinements. Eight designs have paired light/dark modes, giving 46 theme/mode combinations. Stock themes and Reading refinements retain their native palettes; no invented opposite mode is scored.</p><p>The baseline review captured 35 combinations on identical <em>Typography</em> and <em>Code</em> specimens at 1280px desktop and 390px narrow widths, plus desktop <em>Controls</em>. The revision review freshly captured the 11 changed combinations: six custom modes and five Reading palettes. Unchanged originals retain their original measurements and editorial awards. The combined data contains 184 prose/code observations and 46 desktop control observations. All scores are recalculated using the original weights, thresholds, and judgment anchors.</p><p>Baseline desktop observations used 1280 × 720 CSS viewports. New observations use 1280 × 844 and 390 × 844 iframes in the same browser; the typography criteria depend on width, not viewport height. This tests CSS reflow, not a physical device. New screenshots show the first 650px of the specimen below the inspection toolbar; original saved captures may show the whole page. The live comparison supplies the complete pages.</p><h3>Measurement and judgment</h3><ul><li>Body size, leading, paragraph spacing and character-range geometry come from two opening prose paragraphs. Complete-line averages exclude the final line of each paragraph. The short, roughly 490-character sample is a capacity estimate; borderline measures should be retested on a long chapter.</li><li>Each mode is scored independently. The lower light/dark total becomes the theme score, so a strong mode cannot conceal a weaker one. Both viewport widths contribute within each typography category.</li><li>Contrast uses sRGB relative luminance and alpha-composited ancestor colors. Quartz’s horizontal gradient is sampled across the reading column; component gradients and Vapor’s vertical gradient use conservative stop ranges. These gradient estimates require pixel-location verification for sign-off.</li><li>Score measurements cover normal-state sampled text. Hover, focus, active, disabled, visited, selection, every syntax class, icons, assistive technology, zoom, localization, and mobile control text are not certified by this scorecard. Source-level state mappings and spot checks of revised controls are useful but do not constitute a complete accessibility audit.</li><li>The shared specimen omits sidebars, contents panels, marginal notes, and complex Tufte layouts. Three custom themes also have separate SmallDocs demos and Quarto source layers. These component-specific checks are supplementary to the fixed shared rubric.</li><li>Font suitability and design awards are editorial judgments. The same reviewer designed the refinements, so this is a self-review, not an independent study. A 95–98 score means close alignment with this particular short rubric, not proven superior reading or a universal ranking. Small differences should be treated as ties in practice.</li></ul><p class="caption">Reviewed 16 October 2026. Original gallery snapshot: <code>8b0ae2319b36598e4afa397095c159836d567576</code>. Theme revisions and hashes, capture provenance, raw measurements, and calculation code accompany the reports. Original custom source is preserved at tag <code>before-reading-redesign-2026-10-16</code>. No rubric weights changed after refinement.</p></section>"""

def custom_proposals():
    sections=[]
    for id in ['folio','atelier','nocturne']:
        t=BY_ID[id];cfg=json.loads((OUT/f'smalldocs-{id}/src/theme.json').read_text())
        palettes={m:{'p':c['paper'],'i':c['ink'],'a':c['accent'],'c':c['code'],'l':c['line']} for m,c in [('light',cfg['light']),('dark',cfg['dark'])]}
        font='DM Sans' if id=='atelier' else 'Source Serif 4';heading='Libre Caslon Display' if id=='folio' else font
        size=16.66 if id=='atelier' else 18.36;h=39.1 if id=='folio' else 28.05 if id=='atelier' else 31.45
        vars=';'.join('--d'+k+':'+v for k,v in palettes['light'].items())+f';--df:"{font}";--dhf:"{heading}";--ds:{size}px;--dh:{h}px'
        excerpt='The first obligation of a page is to be read. A comfortable line, a generous margin, and an unhurried rhythm do much of the work. Consistency makes the details useful.'
        demos=''.join(f'<div class="demo {"proposed" if proposed else ""}" style="{E(vars)}"><p class="demo-kicker">{"Proposed refinement" if proposed else "Current settings"}</p><h3>A comfortable measure</h3><p>{excerpt}</p><pre>def find_books(books, query):\n    return [b for b in books\n            if query in b.title]</pre><button type="button">Outline action</button></div>' for proposed in [False,True])
        sections.append(f'<section class="custom-proposal"><h3>{t["name"]}: type {t["typography"]}, design {t["design"]["total"]}</h3><p>{E(t["note"])}</p><div class="demo-tools"><label>Excerpt palette <select data-demo-mode data-palettes="{E(json.dumps(palettes))}"><option value="light">Light</option><option value="dark">Dark</option></select></label><span class="caption">An isolated, re-typeset comparison; saved screenshots show the original full layout.</span></div><div class="demo-pair">{demos}</div></section>')
    return ''.join(sections)

PATCH='''/* Candidate refinement; apply to each theme source and re-render before release. */
html main.content p,
html main.content li { line-height: 1.45; }
html main.content p { margin-bottom: 1rem; }
html pre { font-size: .85rem; line-height: 1.5; }
html main.content h2 { font-size: 1.6rem; }
html .quarto-title h1.title { font-size: clamp(2rem, 4vw, 2.9rem); }
html:root, html.quarto-dark:root {
  --sd-body-width: 640px;
  --quarto-hl-at: var(--e-accent);
}
html .btn-outline-primary {
  --bs-btn-color: var(--e-accent);
  --bs-btn-border-color: var(--e-accent);
  --bs-btn-hover-color: var(--e-paper);
  --bs-btn-hover-bg: var(--e-accent);
  --bs-btn-hover-border-color: var(--e-accent);
  --bs-btn-active-color: var(--e-paper);
  --bs-btn-active-bg: var(--e-accent);
  --bs-btn-active-border-color: var(--e-accent);
}
@media (max-width: 575.98px) {
  html pre { font-size: .85rem; }
}'''

PAIRS=[('folio-original','folio'),('atelier-original','atelier'),('nocturne-original','nocturne'),('zephyr','zephyr-reading'),('simplex','simplex-reading'),('pulse','pulse-reading'),('litera','litera-reading'),('darkly','darkly-reading')]
def comparison_table():
    rows=[]
    for old,new in PAIRS:
        a,b=BY_ID[old],BY_ID[new]
        rows.append(f'<tr><th scope="row">{E(b["name"])}</th><td>{a["typography"]} → <strong>{b["typography"]}</strong> <small>(+{b["typography"]-a["typography"]})</small></td><td>{a["design"]["total"]} → <strong>{b["design"]["total"]}</strong> <small>(+{b["design"]["total"]-a["design"]["total"]})</small></td><td><a href="./?group=comparisons&amp;q={new.removesuffix("-reading")}">Compare</a> · <a href="{b["source"]}">Install / source</a></td></tr>')
    return '<div class="table-wrap"><table class="rubric"><caption>Original → refined. Both scales are /100. No combined grand total.</caption><thead><tr><th>Refined theme</th><th>Typography</th><th>Design</th><th>Pages and source</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div><p class="caption">Original measurements and awards are frozen. Revised modes are freshly measured; the weights and judgment anchors are unchanged. Paired custom themes use their lower light/dark score. Stock and Reading themes retain a single native palette.</p>'

def pair_evidence(design):
    result=[]
    for old,new in PAIRS:
        a,b=BY_ID[old],BY_ID[new];mode='dark' if b['paired'] and design else 'light' if b['paired'] else 'original';kind='components' if design else 'typography'
        result.append('<h3>'+E(b['name'])+'</h3><div class="grid">'+evidence(old,mode,kind,caption='<strong>Original.</strong> '+E(a['design']['note'] if design else a['note']))+evidence(new,mode,kind,caption='<strong>Refined.</strong> '+E(b['design']['note'] if design else b['note']))+'</div>')
    return ''.join(result)

def type_report():
    rubric=[
     ('Font and text texture','15','Editorial: 15 for a deliberate, calm text face and clear role separation; 14 for a conventional authored text family; 12 for a capable but generic system stack. Lux 10 for tracked, light body text; Vapor 10 for pervasive glow; Sketchy 6 for handwriting/display texture. Price and license do not earn points.',web('body-text','Body text')+'; '+web('system-fonts','system fonts')+'; '+web('monospaced-fonts','code exception')),
     ('Body size','10','10 when desktop and mobile body are both 15–25px; otherwise 7 in this dataset. All themes fall inside the preferred range. Optical size still needs visual judgment.',web('point-size','Point size')),
     ('Line spacing','20','20 for 1.20–1.45; 17 for >1.45–1.55; 12 for >1.55–1.65; 7 for >1.65–1.80; 3 outside those bands, except 12 for 1.10–<1.20. The lower desktop/mobile band wins. These deduction bands are ours.',web('line-spacing','Line spacing')),
     ('Line length and reflow','15','Desktop /10: 45–90 characters gets 10; 40–<45 or >90–100 gets 8; 35–<40 or >100–110 gets 5; 30–<35 or >110–120 gets 2; otherwise 0. Mobile /5: 45–90 gets 5; 35–<45 gets 4; 30–<35 gets 2; otherwise 0. Page overflow deducts 2 mobile points.',web('line-length','Line length')+'; '+web('responsive-web-design','responsive web design')),
     ('Paragraphs and negative space','10','Paragraph separation /5: a gap of 0.50–1.00em at both widths gets 5; 0.40–1.30em gets 4; otherwise 2. A simultaneous first-line indent deducts 2. Gutters /5: ≥15px and no page overflow gets 5; ≥10px gets 3; otherwise 1. Gutter cutoffs are our operational checks, not Butterick’s.',web('space-between-paragraphs','Paragraph spacing')+'; '+web('page-margins','page margins')),
     ('Hierarchy and restraint','10','Section scale /4: H2/body ≤1.4 gets 4; ≤1.8 gets 3; otherwise 1. Italic H2 deducts 1; uppercase H2 deducts 2, floor 0. Grouping /3: more space before H3 than after, and no H2/prose overlap, gets 3; otherwise 1. Title/body ≤2 gets 3, ≤2.8 gets 2, otherwise 1. Ratios are our scoring proxy, not an author-mandated scale.',web('headings','Headings')+'; '+web('space-above-and-below','space above and below')),
     ('Code typography','10','Size /4 uses the smaller desktop/mobile code size: ≥14px gets 4; ≥13 gets 3; ≥12 gets 2; below 12 gets 1. Appropriate monospace earns 3; contained horizontal code scrolling without page overflow earns 3, otherwise 1. This code-size threshold is our SmallDocs criterion.',web('monospaced-fonts','Monospaced fonts')),
     ('Text color and contrast','10','Body /4: ≥4.5:1 gets 4, ≥3 gets 2, otherwise 0. Link, inline code, and worst sampled syntax token each /2: ≥4.5 gets 2, ≥3 gets 1, otherwise 0. Use the low end of a gradient range. These numeric checks come from WCAG, not Butterick.',web('color','Color')+'; <a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html">WCAG contrast</a>')]
    rows=''.join(f'<tr><td><strong>{a}</strong></td><td>{b}</td><td>{c}</td><td>{d}</td></tr>' for a,b,c,d in rubric)
    body=toc([('changes','Before and after'),('rubric','100-point rubric'),('scores','All 38 themes'),('evidence','Visual evidence'),('details','Every deduction'),('method','Method')])
    body+='<section id="changes"><h2>Eight revisions, the same scorecard</h2><p>The changes are implemented in editable theme sources, rebuilt, and measured on the same text. The original custom snapshots and the unchanged bundled Bootswatches remain visible beside their revisions.</p>'+comparison_table()+'<p><a href="./?group=comparisons&amp;page=typography.html">Compare all eight pairs on the actual pages →</a></p><div class="callout"><p>Typography gains mainly come from more controlled leading and line length, quieter headings, and readable code on phones. This is a self-review against a short, prescriptive rubric. Close alignment is not proof that a theme reads better for everyone; retain the visual character you prefer.</p></div><h3>What changed</h3><ul><li><strong>Folio, Atelier, Nocturne:</strong> keep their fonts and palettes; reduce prose leading to 1.45, bound prose at 640px, quiet headings, keep code at 14.45px, and complete theme-aware controls. Folio and Nocturne also repair faint decorator syntax.</li><li><strong>Zephyr, Simplex, Pulse Reading:</strong> narrower prose, restrained headings, local IBM Plex Mono, consistent form and status surfaces. The source stock CSS remains pinned separately.</li><li><strong>Litera Reading:</strong> continue Georgia through lists; darken blue links; repair secondary actions and status labels.</li><li><strong>Darkly Reading:</strong> retain charcoal and Lato; lighten outline links and use readable text on muted status surfaces.</li></ul><p>The original stock choices remain useful: Zephyr for a modern UI, Simplex for a quiet red accent, Pulse for purple. Litera and Darkly benefit most from the documented control repairs.</p></section>'
    body+='<section id="rubric"><h2>The typography rubric: 100 points</h2><p>Butterick identifies font, size, leading, and line length as the core body-text choices. They receive 60 points here. The remaining 40 cover paragraph structure, heading restraint, code, and text contrast. Weights and deduction bands are this review’s choices and are unchanged from the original assessment.</p><div class="table-wrap"><table class="rubric"><thead><tr><th>Criterion</th><th>Points</th><th>How points are granted</th><th>Basis</th></tr></thead><tbody>'+rows+'</tbody></table></div><p><strong>Adaptations:</strong> narrow screens receive partial credit for 35–44 characters rather than requiring smaller text to reach 45. Fonts are judged by visible suitability, not purchase price. Heading ratios and code-size cutoffs are operational proxies chosen for this review, not rules dictated by Butterick. <a href="typography-guide.html">Read the illustrated typography principles.</a></p></section>'
    body+='<section id="scores"><h2>All 38 designs, scored</h2>'+table()+'</section>'
    body+='<section id="evidence"><h2>The revisions in actual pages</h2><p>These are browser captures of the generated themes. Old captures and new captures have different viewport heights; compare type relationships and line lengths, not image height.</p>'+pair_evidence(False)+'</section>'
    body+='<section id="details"><h2>Every theme and every deduction</h2><p>Each entry exposes category points, measured values, contrast flags, and a live specimen. A high total does not waive a contrast repair.</p>'+score_details()+'</section>'+METHOD
    body+='<section class="sources"><h2>Source notes</h2><p>Matthew Butterick, <a href="https://practicaltypography.com/">Practical Typography</a>: '+', '.join(web(k,l) for k,l in [('typography-in-ten-minutes','body-text priorities'),('websites','web principles'),('line-spacing','leading'),('line-length','measure'),('headings','headings')])+'. Numeric contrast uses <a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html">WCAG normal-text guidance</a>. Weights, examples, and scores are our interpretation.</p></section>'
    page('typography-report.html','How well do the themes read?','01 / Assessment / Butterick','A fixed typography scorecard for 38 designs, including eight original/refined pairs and fresh measurements of every changed mode.',body)

def design_report():
    criteria=[
      ('Hierarchy','25','Primary content leads; secondary details recede; controls have clear priority. Consider size, weight, tone, and whitespace together.','36–47, 54–59'),
      ('Spacing and grouping','20','Related items sit closer together; section gaps are distinct from paragraph gaps; repeated forms and panels follow a consistent rhythm.','66–74, 96–99'),
      ('Color and contrast','20','Body /4, normal-state controls /4, body links /2, coherent palette /5, non-color cues /3, stable reading surface /2. Measurement and judgment are shown separately.','42–44, 158–168, 202–206'),
      ('Layout and responsive fit','15','Give prose the width it needs; keep alignment intentional; adjust large display elements separately from small reading text and code.','76–81, 92–95, 114–116'),
      ('Surfaces and restraint','10','Panels and controls are distinguishable; shadows, borders and gradients convey structure without becoming the content. Flat designs can earn full marks.','190–192, 224–232, 238–241'),
      ('Personality and fit','10','A coherent combination of fonts, colors and shapes /6; suitability for the requested elegant documentation brief /4. The second part is our project-specific adaptation.','20–26')]
    rows=''.join(f'<tr><td><strong>{a}</strong></td><td>{b}</td><td>{c}<br>{book(d)}</td></tr>' for a,b,c,d in criteria)
    body=toc([('changes','Before and after'),('rubric','Design rubric'),('scores','All scores'),('evidence','Visual evidence'),('details','Theme details'),('method','Method')])
    body+='<section id="changes"><h2>Keep the identities; repair the reading surface</h2><p>Folio remains the literary/CRBooks direction, Atelier the precise studio, and Nocturne the warm evening palette. The five Reading themes preserve their Bootswatch character while giving prose, code, and controls clearer roles.</p>'+comparison_table()+'<p><a href="./?group=comparisons&amp;page=components.html">Compare the original and revised controls →</a> · <a href="ui-design-guide.html">Read the illustrated UI principles</a></p><div class="callout"><p>The strongest practical shortlist is the three custom refinements, Zephyr Reading for a modern light UI, Litera Reading for serif prose, and Darkly Reading for a conventional dark UI. Simplex and Pulse Reading are useful accent alternatives. Prefer the character that serves the document; differences of a few design points are editorial calls.</p></div><p>Design gains come from quieter hierarchy, consistent grouping, appropriate prose width, and repaired text contrast. Personality points are retained rather than increased merely because a theme is newly revised. All unchanged themes retain their original awards. Sampled revised text clears the rubric’s contrast threshold; interaction states and every component still need project-specific checks.</p></section>'
    body+='<section id="rubric"><h2>The visual design rubric: 100 points</h2><p>Adapted from Adam Wathan and Steve Schoger’s <a href="https://refactoringui.com/">Refactoring UI</a>. Page ranges refer to the reviewed 252-page edition. The principles are selectively paraphrased; examples are original HTML. No book pages, PDF, or extracts are published.</p><div class="table-wrap"><table class="rubric"><thead><tr><th>Criterion</th><th>Points</th><th>Full-credit behavior and source pages</th></tr></thead><tbody>'+rows+'</tbody></table></div><h3>Judgment anchors</h3><p>100% = clear and coherent with no material issue in the inspected specimen; 75% = functional with a specific distraction or inconsistency; 50% = repeated conflict; 25% = substantial difficulty; 0 = the criterion is defeated. Intermediate awards express the strength of observed issues. Notes explain each theme’s diagnosis; these are self-review judgments, not an independent experiment.</p><h3>Color scoring</h3><p>Body: 4 at ≥4.5:1, 2 at ≥3, otherwise 0. Links: 2 at ≥4.5, 1 at ≥3, otherwise 0. Controls: 4 when all sampled normal-state labels clear 4.5; 3 for one failure ≥3; 2 for at most two other failures; 1 for several failures all ≥3; otherwise 0. The remaining 10 judge coherent palette, non-color cues, and a stable reading surface. Paired themes use the lower result. These numeric checks come from <a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html">WCAG guidance</a>.</p><p>The sources are complementary: Refactoring UI suggests 45–75 characters and relates leading to size and width; Butterick usually suggests 45–90 characters and 1.20–1.45 leading. Refactoring UI is comfortable with system fonts. Neither requires a serif face, shadows, or a rigid modular scale.</p></section>'
    body+='<section id="scores"><h2>All 38 designs, on both axes</h2>'+table(True)+'</section>'
    body+='<section id="evidence"><h2>Control repairs and visual continuity</h2>'+pair_evidence(True)+'</section>'
    body+='<section id="details"><h2>All design observations and component flags</h2><p>Expand a theme for awarded category points and each sampled control-label ratio. Only normal states contribute to the measured score.</p>'+score_details(True)+'</section>'+METHOD
    body+='<section class="sources"><h2>Sources</h2><p>Adam Wathan and Steve Schoger, <a href="https://refactoringui.com/">Refactoring UI</a>. Relevant page ranges appear in the rubric. <a href="ui-design-guide.html">Our companion guide</a> illustrates the principles with original HTML examples. <a href="https://practicaltypography.com/">Butterick’s Practical Typography</a> supplies the separate typography assessment.</p></section>'
    page('visual-design-report.html','Which themes form a convincing design?','02 / Assessment / Refactoring UI','A fixed design scorecard for hierarchy, grouping, color, responsive structure, surfaces, and fit—before and after eight refinements.',body)

def pair(left,right,cls=''):
    return f'<div class="grid {cls}"><div class="example">{left}</div><div class="example">{right}</div></div>'

def type_guide():
    sample='A good reading page gives the argument a quiet place to unfold. The reader should be able to follow a sentence, find the next line, and recognize a new section without studying the interface. Type size, line length, and line spacing work together. Extra space helps when it reveals a relationship; too much can pull a paragraph apart. A strong theme makes these decisions deliberately and then carries them consistently through the rest of the document.'
    body=toc([('core','The reading system'),('lab','Try the settings'),('hierarchy','Hierarchy'),('space','Space'),('details','Type details'),('code','Code'),('sources','Sources')])
    body+='''<section id="core"><h2>Design the body before the display</h2><p>The body is where a documentation reader spends most of their time. Choose its face, optical size, line spacing, and measure together. Then make navigation, headings, captions, and code fit that reading system. These notes paraphrase Butterick’s guidance and use original examples; they are not a replacement for the book.</p><div class="grid three"><div class="card"><span class="stat">15–25 <small>CSS px</small></span><h3>Body size</h3><p>A starting range for web reading, adjusted for the face’s apparent size.</p><p class="small">'''+web('point-size','Point size')+'''</p></div><div class="card"><span class="stat">1.20–1.45</span><h3>Usual leading</h3><p>Enough space to follow lines without dissolving the paragraph.</p><p class="small">'''+web('line-spacing','Line spacing')+'''</p></div><div class="card"><span class="stat">45–90 <small>characters</small></span><h3>Average line length</h3><p>Count actual rendered characters, including spaces. A CSS width alone cannot establish it.</p><p class="small">'''+web('line-length','Line length')+'''</p></div></div></section>'''
    body+=f'''<section id="lab"><h2>A small reading laboratory</h2><p>Change one setting at a time, then judge the complete paragraph. The rendered line counter uses the actual glyph positions, not a guessed conversion from <code>ch</code>. At narrow window sizes the container limits the requested width.</p><div class="lab"><div class="lab-controls"><label>Body size <output id="size-out">18px</output><input id="lab-size" type="range" min="14" max="25" value="18" step=".5"></label><label>Line height <output id="leading-out">1.45</output><input id="lab-leading" type="range" min="1.1" max="1.9" value="1.45" step=".05"></label><label>Text width <output id="width-out">640px</output><input id="lab-width" type="range" min="280" max="900" value="640" step="20"></label></div><div class="lab-sheet"><p id="lab-text">{sample}</p></div><output id="lab-count" class="lab-stats" aria-live="polite">Measuring rendered lines…</output></div><p class="caption">A short sample is sensitive to word lengths and paragraph endings. Full-line means estimate capacity; the all-line mean includes the final short line. Neither replaces reading a long chapter.</p><h3>The rhythm changes even when the words do not</h3><div class="grid three">'''+''.join(f'<div class="example prose"><span class="label">Leading {v}</span><p style="line-height:{v}">A reader should be able to find the next line without losing the sentence. The space between lines changes the texture of the whole paragraph.</p></div>' for v in ['1.20','1.45','1.75'])+'''</div><p class="caption">These are comparison settings, not universal good/bad labels. Font proportions and line length influence the result.</p></section>'''
    body+='<section id="hierarchy"><h2>Make headings useful without making them loud</h2><p>Start with spacing and a modest change of weight or size. Use a small number of distinguishable levels. Butterick prefers restrained, left-aligned section headings and generally favors bold over italic; a literary italic can still be a conscious design exception. '+web('headings','Read the heading guidance')+'.</p>'+pair('<span class="label bad-label">Several competing signals</span><h3 class="bad-h">A smaller thought</h3><p style="font-family:var(--serif)">The section heading is bigger, bold, tracked, and capitalized all at once. The paragraph must work harder to reclaim attention.</p>','<span class="label good-label">One clear signpost</span><h3 class="good-h">A smaller thought</h3><p style="font-family:var(--serif)">A modest weight change and a larger gap above the heading reveal the structure while keeping the argument in view.</p>')+'</section>'
    body+='<section id="space"><h2>Space should reveal relationships</h2><p>A paragraph needs a visible beginning: either an indent or a gap, usually not both. Butterick describes paragraph separation around half to one body em. Around headings, leave more space above than below so the heading belongs to its following text. '+web('space-between-paragraphs','Paragraph spacing')+'; '+web('space-above-and-below','heading spacing')+'.</p>'+pair('<span class="label">Disconnected paragraphs</span><p class="type-sample" style="margin-bottom:48px">An idea begins here and is developed in a paragraph.</p><p class="type-sample">The next paragraph belongs to the same argument, but the oversized gap suggests a new section.</p>','<span class="label">A continuous argument</span><p class="type-sample" style="margin-bottom:16px">An idea begins here and is developed in a paragraph.</p><p class="type-sample">The next paragraph belongs to the same argument. A clear but modest gap marks the new start.</p>')+'<h3>Let the outer margin do its work</h3><p>Set the reading width first, then accept the space around it. Do not stretch prose just because the viewport is wide. Margin size is a consequence of readable measure rather than a fixed decorative number. '+web('page-margins','Page margins')+'.</p><div class="example" style="background:#e5ebdd"><div style="max-width:560px;background:white;padding:24px;margin:auto;font:18px/1.45 var(--serif)">A centered text block can occupy only part of a wide page. The empty space protects the reading line and gives the prose a stable place to live.</div></div></section>'
    body+='<section id="details"><h2>Choose a coherent text texture</h2><p>Use a face suited to the role, with real emphasis styles and reliable fallbacks. A serif is not automatically better than a sans. Butterick is particularly skeptical of most free and system fonts; our review treats font cost as separate from visible quality and judges whether the choice suits sustained reading.</p>'+pair('<span class="label">Lowercase with extra tracking</span><p class="type-sample" style="letter-spacing:.1em">Reading is a continuous activity. Excess space between lowercase letters can weaken the shapes of words.</p>','<span class="label">Ordinary spacing; tracked short capitals</span><p class="type-sample">Reading is a continuous activity. The font already contains spacing decisions for ordinary lowercase text.</p><p style="font-size:13px;letter-spacing:.08em">FIELD NOTES / READING</p>')+'<p class="caption">Butterick recommends extra tracking for short runs of capitals, usually 0.05–0.12em; ordinary lowercase generally does not need it. '+web('letterspacing','Letterspacing')+'.</p><h3>Keep punctuation and emphasis deliberate</h3><div class="grid"><div class="example"><span class="label">Typographic prose</span><p class="type-sample">“Read slowly,” she said. The reader’s notes — concise, precise, and useful — became a small reference.</p><p class="small">Curly quotes and apostrophes, one space after a sentence, proper dashes, and restrained emphasis support the text.</p></div><div class="example"><span class="label">Machine syntax</span><pre>query = "room"\nslug = "a-room-with-a-view"</pre><p class="small">Code keeps literal straight quotes and hyphens because those characters have program meaning.</p></div></div><p class="caption">'+web('straight-and-curly-quotes','Quotation marks')+'; '+web('bold-or-italic','bold or italic')+'; '+web('hyphens-and-dashes','hyphens and dashes')+'. Content punctuation is shared by all gallery specimens, so it is not used to invent differences between themes.</p></section>'
    body+='<section id="code"><h2>Give code a distinct, readable role</h2><p>Butterick’s objection to monospace concerns ordinary body text; he explicitly recognizes code as a useful exception. A documentation theme needs a clear monospace face, preserved indentation, distinguishable symbols, and a contained scroll area. '+web('monospaced-fonts','Monospaced fonts')+'.</p>'+pair('<span class="label">Our current mobile code size: 11.9px</span><pre style="font-size:11.9px">0O  1Il  {}[]()  =&gt; != &lt;=\nbooks = find_books(library, "room")</pre>','<span class="label">Trial size: 14.5px</span><pre style="font-size:14.5px">0O  1Il  {}[]()  =&gt; != &lt;=\nbooks = find_books(library, "room")</pre>')+'<p class="caption">The larger code threshold is our SmallDocs design choice. It is not a numeric code-font rule from Butterick.</p><h3>Contrast belongs to the reading system</h3><p>Restrained color helps the reader understand what is a link, an aside, or a syntax token. Check every relevant surface in both modes. Butterick discusses screen comfort and color restraint; the numeric 4.5:1 normal-text threshold comes from <a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html">WCAG</a>, and is a minimum rather than a definition of beauty.</p>'+pair('<span class="label">Faint reading surface</span><p style="color:#7b8ab8;background:#d9e3f1;padding:22px">A 17px paragraph can still be difficult to read when the foreground and background are too similar.</p>','<span class="label">A stronger reading surface</span><p style="color:#25372d;background:#f8f4eb;padding:22px">A calm palette can preserve its warmth while using enough contrast to support sustained reading.</p>')+'<p class="caption">'+web('color','Color')+'. Review main prose, small captions, links, code, and supporting text separately; a good body ratio does not guarantee the rest.</p></section>'
    body+='<section id="sources"><h2>Use this guide when refining a theme</h2><ol><li>Read a long, representative chapter before adjusting ornamental details.</li><li>Set body face, size, measure and leading as one system.</li><li>Check paragraphs, headings, lists, links, captions, code and tables in both modes.</li><li>Inspect narrow layouts with readable text and contained code scrolling.</li><li>Keep deliberate exceptions, and document why they help the intended reader.</li></ol><p class="sources">The references above point to Matthew Butterick’s <em>Practical Typography</em>. For his web-specific position on design identity, see '+web('websites','Websites')+'. The weights and partial-credit bands used in the <a href="typography-report.html">assessment</a> are our own. All demonstrations on this page are original HTML compositions.</p></section>'
    script='''const lp=document.querySelector('#lab-text');const inputs=['size','leading','width'].map(k=>document.querySelector('#lab-'+k));function updateLab(){const [s,l,w]=inputs.map(e=>Number(e.value));lp.style.fontSize=s+'px';lp.style.lineHeight=l;lp.style.maxWidth=w+'px';document.querySelector('#size-out').textContent=s+'px';document.querySelector('#leading-out').textContent=l.toFixed(2);document.querySelector('#width-out').textContent=w+'px';const n=lp.firstChild,lines=[];for(let i=0;i<n.length;i++){const r=document.createRange();r.setStart(n,i);r.setEnd(n,i+1);const b=r.getBoundingClientRect();if(b.width<.1)continue;let line=lines.find(v=>Math.abs(v.y-b.y)<2);if(!line){line={y:b.y,n:0};lines.push(line);}line.n++;}const full=lines.slice(0,-1),mean=a=>a.reduce((s,v)=>s+v.n,0)/a.length;document.querySelector('#lab-count').textContent='Rendered width '+Math.round(lp.getBoundingClientRect().width)+'px · '+(full.length?mean(full).toFixed(1):'—')+' chars / complete line · '+mean(lines).toFixed(1)+' including final line';}inputs.forEach(e=>e.addEventListener('input',updateLab));document.fonts.ready.then(updateLab);window.addEventListener('resize',updateLab);'''
    page('typography-guide.html','A practical guide to reading typography','03 / Illustrated reference / Butterick','The principles behind the typography rubric, with adjustable settings and original visual examples for documentation themes.',body,script)

def ui_guide():
    body=toc([('hierarchy','Hierarchy'),('grouping','Grouping'),('color','Color'),('layout','Layout'),('surfaces','Surfaces'),('identity','Identity'),('apply','Apply it')])
    body+='''<p class="section-intro">This is a selective working summary of <em>Refactoring UI</em> for documentation themes. The examples below are original HTML. Page references identify the reviewed edition; the <a href="https://refactoringui.com/">official book site</a> provides public context. The book covers much more than this task, including product workflows, photos, and empty states.</p><section id="hierarchy"><h2>1. Give the reader an obvious priority</h2><p>Make the main task stand out by quieting competing information. Weight, tone, and spacing can establish hierarchy without enormous titles or tiny supporting text. Secondary information should remain readable.</p>'''+book('36–47, 54–59')+pair('<span class="label">Every element competes</span><span class="noisy">READING NOTEBOOK</span><span class="noisy">UPDATED TODAY</span><span class="noisy">12 CHAPTERS</span><span class="noisy">OPEN NOTEBOOK →</span>','<span class="label">The content leads</span><p class="quiet">Reading notebook</p><div class="title">Notes worth returning to</div><p>A small collection of ideas from twelve chapters.</p><p class="quiet">Updated today</p><span class="ui-button">Open notebook →</span>')+'<h3>Supporting text does not need to shrink</h3>'+pair('<span class="label">De-emphasis through smallness</span><div class="title">A useful function</div><p class="tiny">Updated yesterday · Python · A short example</p>','<span class="label">De-emphasis through tone</span><div class="title">A useful function</div><p class="quiet">Updated yesterday · Python · A short example</p>')+'</section>'
    body+='<section id="grouping"><h2>2. Make groups easier to recognize than gaps</h2><p>Related elements need less space between them than unrelated groups. A heading should sit closer to the content it introduces. Consistent spacing values help the whole system feel intentional, but a rigid arithmetic formula does not replace visual judgment.</p>'+book('66–74, 96–99')+pair('<span class="label">Ambiguous grouping</span><span class="ui-label">Notebook title</span><span class="ui-field" style="margin:22px 0">Ideas worth keeping</span><span class="ui-label">Collection</span><span class="ui-field" style="margin:22px 0">Reading notes</span>','<span class="label">Clear form groups</span><div class="group"><span class="ui-label">Notebook title</span><span class="ui-field" style="margin-bottom:0">Ideas worth keeping</span></div><div class="group"><span class="ui-label">Collection</span><span class="ui-field" style="margin-bottom:0">Reading notes</span></div>')+'<h3>A small working spacing vocabulary</h3><div class="example"><div class="scale-bars">'+''.join(f'<div><i style="height:{v}px"></i>{v}px</div>' for v in [4,8,12,16,24,32,48])+'''</div><p class="caption" style="margin-top:20px">An illustrative token set, not a required sequence from the book. Use fine steps for small controls and more distinct steps for larger spaces.</p></div><div class="callout"><p>Generous outer space can be useful while paragraph leading is still too loose. “Whitespace” is not one interchangeable quantity: margins, line spacing, paragraph separation, and section gaps have different jobs.</p></div></section>'''
    body+='<section id="color"><h2>3. Build a palette with readable roles</h2><p>Use a small set of coherent tones for primary, secondary, and tertiary information. On colored surfaces, choose supporting text to work with that hue rather than adding a generic pale grey. Confirm contrast in the actual composition, and give meaning a cue besides color.</p>'+book('42–44, 142–160, 162–168')+pair('<span class="label">A bright surface is not enough</span><div class="status bad">The note has been saved.</div><p class="small" style="margin-top:16px">White on a pastel panel can look friendly while becoming hard to read.</p>','<span class="label">Color supports the message</span><div class="status">✓ The note has been saved.</div><p class="small" style="margin-top:16px">Darker text on a pale surface keeps the palette, while the symbol and words carry the meaning.</p>')+'<h3>Dark mode needs its own relationships</h3><div class="grid"><div class="example" style="background:#1c2030;color:#ede8de"><span class="label" style="color:#b5b6c3">A stable dark reading surface</span><div class="title" style="color:#e2bd82">A chapter worth keeping</div><p>Main text remains strong. Supporting text can recede without vanishing.</p><p style="color:#b5b6c3;font-size:15px">Updated today · Notes on a chapter</p></div><div class="example"><span class="label">Roles before exact hues</span><div class="swatches"><i style="background:#f8f4eb"></i><i style="background:#efe9dc"></i><i style="background:#5f6b62"></i><i style="background:#254f38"></i><i style="background:#25372d"></i></div><p>Paper, panel, supporting text, accent, main text. Define a role for each tone, then check the foreground/background pairs that actually occur.</p></div></div><p class="caption">The book supports accessible color choices. For the current numeric requirements, use <a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html">W3C’s WCAG contrast guidance</a>. Do not use a pale disabled-looking control as a template for enabled actions.</p></section>'
    body+='<section id="layout"><h2>4. Give each kind of content the width it needs</h2><p>The full browser width is an available canvas, not an obligation. Paragraphs benefit from a controlled measure; tables, diagrams, and code may need more room. Refactoring UI suggests 45–75 characters for paragraphs, allowing some wider cases with care.</p>'+book('76–81, 114–116')+'<div class="example" style="background:#e7ecdf"><div class="read-surface" style="max-width:610px;margin:auto"><div class="title">A bounded reading column</div><p>A short paragraph can remain comfortable while a larger data display uses more of the available canvas. Different content widths can belong to the same coherent page.</p></div><pre style="margin-top:22px;background:#f7f9f3">Title                         Author                  Year\nA Room with a View             E. M. Forster           1908\nPride and Prejudice             Jane Austen             1813</pre></div><h3>Large and small elements need different responsive changes</h3><p>Reduce large display elements more than already-small reading text. Keeping the same size ratios at every breakpoint can leave a phone with giant headings and tiny code. Line spacing should also respond to text size and measure rather than being uniform everywhere.</p>'+book('92–95, 122–125')+pair('<span class="label">A scaled-down desktop</span><div class="phone-outline"><h3 style="font-size:34px">A title fills the phone</h3><p style="font-size:14px">The body shrinks to make room for the display.</p><pre style="font-size:11.9px">find_books(library, "room")</pre></div>','<span class="label">A considered narrow layout</span><div class="phone-outline"><h3>A title makes room</h3><p style="font-size:17px">The heading becomes quieter while the body remains comfortable.</p><pre style="font-size:14.5px">find_books(library, "room")</pre></div>')+'</section>'
    body+='<section id="surfaces"><h2>5. Separate surfaces with the smallest useful signal</h2><p>A border, a background shift, whitespace, or a shadow can each distinguish a group. Use the tool that fits the hierarchy. Flat designs can convey layers; decorative depth does not earn points by itself. Accent borders can add character without filling the whole component with intense color.</p>'+book('190–192, 224–226, 238–241')+pair('<span class="label">Repeated outlines compete</span><div class="boxed"><div class="boxed"><strong>A reading note</strong></div><div class="boxed">The explanation sits in another outlined box.</div><div class="boxed" style="margin-bottom:0">A third border adds another competing edge.</div></div>','<span class="label">A surface and a single accent</span><div class="surface accent"><div class="title">A reading note</div><p>The group is clear through spacing and a quiet surface. One accent supplies enough emphasis.</p></div>')+'<h3>Keep decoration behind the hierarchy</h3><p>The book allows subtle gradients and patterns; the important constraint is that they support rather than interfere with content. A decorative header can carry the personality while long prose has a stable foreground/background relationship.</p>'+book('202–206, 228–232')+'<div class="photo-free"><h3>A little visual character</h3><div class="read-surface"><p>The reading surface stays stable. The decorative background belongs to the surrounding frame, not to every line of text.</p></div></div></section>'
    body+='<section id="identity"><h2>6. Make the personality consistent with the purpose</h2><p>Type, color, shape, and language work together to suggest a character. A playful design is not inherently poor design, but it may be wrong for an elegant documentation site. Neutral sans, literary serif, and a warm dark palette can all be coherent directions.</p>'+book('20–26, 108–112')+'<div class="grid three"><div class="example" style="background:#f8f4eb;color:#25372d"><span class="label">Literary</span><h3 style="font:32px/1.1 \'Libre Caslon Display\';color:#254f38">The reading room</h3><p style="font:18px/1.45 var(--serif)">Paper, a text serif, and a measured accent make a quiet editorial voice.</p></div><div class="example" style="background:#fbfcfa;color:#253e42"><span class="label">Studio</span><h3 style="font-weight:400;color:#176a70">A useful system</h3><p>A clean sans face, careful grouping, and one fine rule can feel precise without feeling generic.</p></div><div class="example" style="background:#1c2030;color:#ede8de"><span class="label" style="color:#b5b6c3">Evening</span><h3 style="font-family:var(--serif);color:#e2bd82">After hours</h3><p style="font-family:var(--serif)">A dark ink surface and a selective warm accent give the same content another mood.</p></div></div><p class="caption">These original examples echo the intended roles of Folio, Atelier, and Nocturne. They do not reproduce a layout from the book.</p></section>'
    body+='<section id="apply"><h2>A theme review that leads to action</h2><ol><li>Start with the actual task: reading, finding a section, understanding code, or using a control.</li><li>Read the page in grey or with accents mentally removed. Is its hierarchy still clear?</li><li>Check grouping before adding a divider, shadow, or more color.</li><li>Inspect text on every surface, including secondary buttons, messages, captions, and code.</li><li>Review both modes and narrow widths; do not shrink small text to preserve a desktop composition.</li><li>Keep a few coherent tokens for space, type, surfaces, and accents. Verify the generated page, not only the token list.</li></ol><p><a href="visual-design-report.html">The design assessment</a> applies these principles to all 38 themes. <a href="typography-report.html">The typography assessment</a> supplies a separate, more prescriptive reading score.</p><div class="callout"><p>Neither guide makes a mathematical ratio a substitute for judgment. The strongest evidence is a readable page, clear relationships, and a consistent response to real content.</p></div></section>'
    body+=f'<section class="sources"><h2>Source</h2><p>Adam Wathan and Steve Schoger, <em>Refactoring UI</em>, <a href="{E(BOOK)}">official book site</a>. Page ranges above refer to the reviewed 252-page edition. The guidance has been selectively paraphrased for SmallDocs; illustrations, example copy, and this review’s score weights are original. No book PDF, page images, or extracts are distributed.</p></section>'
    page('ui-design-guide.html','A practical guide to visual structure','04 / Illustrated reference / Refactoring UI','An illustrated working summary of hierarchy, grouping, color, surfaces, responsive layout, and coherent theme personality.',body)

if __name__=='__main__':
    type_report();design_report();type_guide();ui_guide()
    print('Built four HTML files in',OUT)
